const credentialTypeFor = (authentication: string): string =>
	authentication === "oAuth2" ? "videoGenOAuth2Api" : "videoGenApi";

const sleep = async (ms: number): Promise<void> =>
	new Promise((resolve) => {
		const timeout = globalThis.setTimeout;
		timeout(resolve, ms);
	});

const parseMaybeJson = (value: unknown, key: string, jsonKeys: string[]): unknown => {
	if (!jsonKeys.includes(key) || typeof value !== "string") {
		return value;
	}
	const trimmed = value.trim();
	if (trimmed === "") {
		return undefined;
	}
	return JSON.parse(trimmed);
};

const pollWorkflowRun = async (
	ctx: IExecuteFunctions,
	credentialType: string,
	workflowRunId: string,
): Promise<IDataObject> => {
	const startedAt = Date.now();
	for (;;) {
		const run = (await ctx.helpers.httpRequestWithAuthentication.call(ctx, credentialType, {
			method: "GET",
			url: `${BASE_URL}/v1/workflows/runs/${encodeURIComponent(workflowRunId)}`,
			json: true,
		})) as IDataObject;
		const status = run.status;
		if (status === "succeeded" || status === "failed" || status === "cancelled") {
			if (status !== "succeeded") {
				const error = run.error;
				const message =
					error != null && typeof error === "object" && "message" in error
						? String(Reflect.get(error, "message"))
						: `Workflow run ${String(status)}`;
				throw new NodeApiError(ctx.getNode(), { message });
			}
			return run;
		}
		if (Date.now() - startedAt > POLL_TIMEOUT_MS) {
			throw new NodeApiError(ctx.getNode(), { message: "Timed out waiting for workflow run" });
		}
		await sleep(POLL_INTERVAL_MS);
	}
};

