	async execute(this: IExecuteFunctions): Promise<INodeExecutionData[][]> {
		const items = this.getInputData();
		const returnData: INodeExecutionData[] = [];
		const authentication = this.getNodeParameter("authentication", 0) as string;
		const credentialType = credentialTypeFor(authentication);

		for (let i = 0; i < items.length; i++) {
			const operation = this.getNodeParameter("operation", i) as string;
			const spec = WORKFLOW_STARTS[operation];
			if (spec == null) {
				throw new NodeApiError(this.getNode(), { message: `Unsupported operation: ${operation}` });
			}

			const body: IDataObject = { autoExport: true };
			for (const key of spec.requiredBodyKeys) {
				body[key] = parseMaybeJson(this.getNodeParameter(key, i), key, spec.jsonKeys) as IDataObject[string];
			}
			const additional = this.getNodeParameter("additionalFields", i, {}) as IDataObject;
			for (const [key, value] of Object.entries(additional)) {
				body[key] = parseMaybeJson(value, key, spec.jsonKeys) as IDataObject[string];
			}

			const started = (await this.helpers.httpRequestWithAuthentication.call(this, credentialType, {
				method: spec.method,
				url: `${BASE_URL}${spec.path}`,
				body,
				json: true,
			})) as IDataObject;

			const workflowRunId = started.workflowRunId;
			if (typeof workflowRunId !== "string" || workflowRunId === "") {
				throw new NodeApiError(this.getNode(), { message: "Workflow start did not return a run id" });
			}

			const run = await pollWorkflowRun(this, credentialType, workflowRunId);
			returnData.push({ json: run });
		}

		return [returnData];
	}
